// Process individual action capture
const action = $json;

// Validate action data
if (!action.type || !action.timestamp) {
  return [{
    json: {
      success: false,
      error: 'Invalid action data',
      received: action
    }
  }];
}

// Process and store action
const processedAction = {
  sessionId: action.sessionId || `session_${Date.now()}`,
  actionType: action.type,
  element: action.element || '',
  value: action.value || '',
  url: action.url || '',
  timestamp: action.timestamp,
  processedAt: new Date().toISOString()
};

console.log('Action captured:', processedAction.actionType);

return [{json: processedAction}];

// Return success response for action capture
return [{
  json: {
    success: true,
    message: 'Action captured successfully',
    sessionId: $json.sessionId,
    actionType: $json.actionType,
    timestamp: new Date().toISOString()
  }
}];

// Process test generation request
const request = $json;

// Validate session ID
if (!request.sessionId) {
  return [{
    json: {
      success: false,
      error: 'Session ID required for test generation'
    }
  }];
}

// Prepare data for Gemini
const generationRequest = {
  sessionId: request.sessionId,
  actions: request.actions || [],
  pageTitle: request.pageTitle || '',
  pageUrl: request.pageUrl || '',
  requestedAt: new Date().toISOString()
};

console.log('Preparing test generation for session:', request.sessionId);

return [{json: generationRequest}];

// Create prompt for Gemini AI
const data = $json;
const actions = data.actions || [];

// Build comprehensive prompt
const prompt = `
Generate automated test code based on the following user actions:

Page: ${data.pageTitle || 'Unknown'}
URL: ${data.pageUrl || 'Unknown'}
Session: ${data.sessionId}

Captured Actions:
${actions.map((action, i) => `${i + 1}. ${action.type}: ${action.element} ${action.value ? '= ' + action.value : ''}`).join('\n')}

Please generate:
1. Selenium WebDriver test (Python)
2. Playwright test (JavaScript)
3. Cypress test (JavaScript)

Include:
- Page object pattern
- Assertions and validations
- Error handling
- Wait strategies
- Comments explaining each step

Format as JSON with sections: selenium, playwright, cypress
`;

return [{
  json: {
    prompt: prompt,
    sessionId: data.sessionId,
    actionCount: actions.length
  }
}];

// Process Gemini response and format final output
const geminiResponse = $json.message || $json.text || $json;
const sessionId = $input.first().json.sessionId;

// Clean and structure the response
let testCode = '';
if (typeof geminiResponse === 'string') {
  testCode = geminiResponse;
} else if (geminiResponse.message) {
  testCode = geminiResponse.message;
} else {
  testCode = JSON.stringify(geminiResponse, null, 2);
}

const finalResponse = {
  success: true,
  sessionId: sessionId,
  generatedTests: testCode,
  generatedAt: new Date().toISOString(),
  actionCount: $input.first().json.actionCount || 0
};

console.log('Tests generated for session:', sessionId);

return [{json: finalResponse}];
